// Golden values of the portfolio finance logic (docs/spec/03 §6, §7): the prototype's own render values
// (src/features/pfinance/pfinance.golden.json, generated by scripts/proto-golden-pfinance.ts from the prototype logic
// 4494–4520 run in node) rebuilt from the prototype constants with the pure functions of ./portfolio-finance.
import { describe, expect, it } from 'vitest';
import { money } from '@/lib/format';
import PROTO from '@/server/prototype/prototype-data.json';
import GEN from '@/server/prototype/prototype-generated.json';
import golden from '@/features/pfinance/pfinance.golden.json';
import {
  billingRollup, canSeeMargins, capacityBar, capacityOptions, cashBars, candidateHours, clientProjectsText, lowestCumulative, marginAlert, marginPct,
  netCash, netLabel, parseWeight, priorityScore, rankByScore, scoreDots, validScore, validWeight, verdictOf, verdictText, weightShares, weightSum, weightsOff,
  type BillingLine, type MilestoneState,
} from './portfolio-finance';

/* eslint-disable @typescript-eslint/no-explicit-any */
const P = PROTO as any;
const G = golden as any;
const f = (k: number, signed = false) => money(k, 'en', { signed });
const LO = 'var(--color-accent-300)';
const OK = 'var(--color-text)';

const zoneOf = (code: string) => P.GEO[code]?.zone || P.COUNTRY_ZONE[P.GEO[code]?.country] || 'euna';
const projects = (GEN as any).initialProjects as { code: string; name: string; status: string; budget: number; actual: number; start: string }[];
const inZone = (z: string | null) => projects.filter((p) => !z || zoneOf(p.code) === z);
const AXES = P.SCORE_AXES as [string, string, number][];
const DEFAULT_W = AXES.map(([, , w]) => w);
const ZONES = [null, 'euna', 'afr', 'apac'] as const;

/** Prototype ranking population (logic 4500, SCORES as keyed in the prototype; no Clos/Annulé project is scored). */
const ranked = (z: string | null, w = DEFAULT_W) =>
  rankByScore(inZone(z).filter((p) => P.SCORES[p.code] && !['Clos', 'Annulé'].includes(p.status)).map((p) => ({ ...p, scores: P.SCORES[p.code] as number[] })), w);

describe('scoring and ranking (logic 4497–4503)', () => {
  it.each(ZONES)('zone %s: rank, score, bar width, dots, budget, margin (director) and masked margin (depthead)', (z) => {
    for (const role of ['director', 'depthead']) {
      const g = G.portfolio.en[role][String(z)];
      const see = canSeeMargins(role);
      const rows = ranked(z).map(({ rank, score, item: p }) => {
        const b = P.BILLING[p.code];
        const m = b ? marginPct(b[1], p.budget) : null;
        return {
          rank, code: p.code, score, scoreW: `${score}%`, budget: f(p.budget), marginText: see ? (m != null ? `${m}%` : 'Internal') : '•••',
          marginColor: marginAlert(m) ? LO : OK, axes: p.scores.map((v, i) => ({ l: AXES[i][1], v, dots: scoreDots(v).map((on) => (on ? 'var(--color-accent-500)' : 'var(--color-neutral-800)')) })),
        };
      });
      expect(rows).toEqual(g.rows.map((r: any) => ({ rank: r.rank, code: r.code, score: r.score, scoreW: r.scoreW, budget: r.budget, marginText: r.marginText, marginColor: r.marginColor, axes: r.axes })));
      expect(g.masked).toBe(!see);
    }
  });

  it.each(ZONES)('zone %s: KPI tiles', (z) => {
    const g = G.portfolio.en.director[String(z)];
    const zp = inZone(z);
    const active = zp.filter((p) => P.EXEC_STAGES.includes(p.status));
    const pipe = zp.filter((p) => P.PIPE_STAGES.includes(p.status));
    const top = ranked(z)[0];
    const sum = (xs: { budget: number }[]) => xs.reduce((a, p) => a + p.budget, 0);
    expect([
      [active.length, `${f(sum(active))} committed`],
      [pipe.length, `${f(sum(pipe))} proposed · approved · planning`],
      [top ? top.item.code : '—', top ? top.item.name : ''],
      ['18%', 'Client projects · weighted by contract'],
      [`${Math.round(weightSum(DEFAULT_W) * 100)}%`, 'Edit weights on the right'],
    ]).toEqual(g.kpis.map((k: any) => [k.value, k.sub]));
    expect(G.portfolio.en.depthead[String(z)].kpis[3]).toMatchObject({ value: '•••', sub: 'Directors and PMs only' });
    expect(weightsOff(DEFAULT_W)).toBe(false);
  });

  it('weights card: value, normalised share (default weights)', () => {
    const g = G.portfolio.en.director.null.weights;
    expect(AXES.map(([k, l], i) => ({ k, l, v: String(DEFAULT_W[i]), pct: `${weightShares(DEFAULT_W)[i]}%` }))).toEqual(g);
  });

  it('edited weights recompute the ranking, shares and the sum tile live', () => {
    for (const v of G.weights.en) {
      const w = AXES.map(([k]) => v.weights[k] as number);
      const rows = ranked(null, w).map(({ rank, score, item }) => ({ rank, code: item.code, score, scoreW: `${score}%` }));
      expect(rows).toEqual(v.rows.map((r: any) => ({ rank: r.rank, code: r.code, score: r.score, scoreW: r.scoreW })));
      expect(AXES.map(([k], i) => ({ k, v: String(w[i]), pct: `${weightShares(w)[i]}%` }))).toEqual(v.weightRows);
      const tile = v.kpis[4];
      if (weightSum(w) === 0) {
        // Deliberate deviation: the prototype shows "100%" (Σw || 1) when every weight is 0; the rebuild shows 0 % in LO.
        expect(tile.value).toBe('100%');
        expect([`${Math.round(weightSum(w) * 100)}%`, weightsOff(w)]).toEqual(['0%', true]);
      } else {
        expect([`${Math.round(weightSum(w) * 100)}%`, weightsOff(w) ? LO : OK]).toEqual([tile.value, tile.color]);
      }
      expect(rows[0].code).toBe(v.kpis[2].value);
    }
  });

  it('score formula and input parsing', () => {
    expect(priorityScore([5, 4, 3, 4, 4], DEFAULT_W)).toBeCloseTo(81, 6);
    expect(priorityScore([5, 5, 5, 5, 5], [0, 0, 0, 0, 0])).toBe(0);
    expect(priorityScore([5, 3, 2, 3, 5], [2, 2, 1.6, 1.2, 1.2])).toBeCloseTo(priorityScore([5, 3, 2, 3, 5], DEFAULT_W), 9);
    expect([parseWeight('0.3'), parseWeight(''), parseWeight('abc'), parseWeight('1.5')]).toEqual([0.3, 0, 0, 1.5]);
    expect([validWeight(0.25), validWeight('0,4'), validWeight(1), validWeight(0), validWeight(1.2), validWeight(-0.1), validWeight(NaN), validWeight('x'), validWeight(0.33333)])
      .toEqual([0.25, 0.4, 1, 0, null, null, null, null, 0.333]);
    expect([validScore('3'), validScore(5), validScore('1'), validScore('0'), validScore('6'), validScore('2.5'), validScore(''), validScore('4,0')]).toEqual([3, 5, 1, null, null, null, null, 4]);
    expect(canSeeMargins('pm')).toBe(true);
    expect(canSeeMargins('client')).toBe(false);
  });
});

describe('capacity what-if (logic 4505–4512)', () => {
  const RATES = [140, 90, 60, 70, 40];
  it.each(['WSA-044', 'EWA-051', 'FTU-052', 'RBR-048', 'CER-047'])('%s: demand, bars, gap, verdict, options', (code) => {
    const g = G.portfolio.en.director.null.capacity[code];
    const p = projects.find((x) => x.code === code)!;
    const rows = (P.ROLES as [string, number, number][]).map(([name, cap, cur], i) => {
      const add = candidateHours(p.budget, RATES[i]);
      const b = capacityBar({ capacityH: cap, committedH: cur, addH: add });
      return { name, cap, cur, add, tot: b.totalH, text: `${b.totalH} / ${cap} h`, color: b.over ? LO : 'var(--color-neutral-300)', curW: `${b.committedPct}%`, addW: `${b.candidatePct}%`, capL: `${b.capacityPct}%`, gap: b.gapH };
    });
    expect(rows).toEqual(g.rows);
    const gapH = rows.reduce((a, r) => a + r.gap, 0);
    expect([verdictText(gapH), `${gapH} h over 8 weeks`, capacityOptions(p.name, gapH), f(p.budget), p.start]).toEqual([g.wi.verdict, g.wi.gapText, g.wi.options, g.wi.budget, g.wi.start]);
    expect(g.wi.verdictColor).toBe(verdictOf(gapH) === 'absorbed' ? OK : LO);
  });

  it('verdict bands and the no-gap options', () => {
    expect([verdictOf(0), verdictOf(299), verdictOf(300)]).toEqual(['absorbed', 'overtime', 'hire']);
    expect(verdictText(0)).toBe('Can be absorbed with current capacity');
    expect(verdictText(120)).toBe('Absorbable with 120 h of overtime or one contractor');
    expect(verdictText(1560)).toBe('Needs 12 additional people or a later start');
    expect(capacityOptions('Westfield Solar Array', 0)).toEqual(['No action needed', 'Keep 10% reserve for Harbor Line recovery', 'Delay Metro Signage Line B (non-critical) by 2 weeks']);
  });
});

describe('cash flow & billing (logic 4515–4520)', () => {
  const STATUS: Record<string, MilestoneState> = { Planned: 'planned', Invoiced: 'invoiced', Paid: 'paid' };
  /** billingOf (4515): the contract when one exists (value + signed amendments, "{id} {label before ' ('}"), else BILLING. */
  const billingOf = (code: string, ov: Record<string, string> = {}): [string, number, BillingLine[]] => {
    const c = P.CONTRACTS[code];
    if (!c) {
      const [model, value, ms] = P.BILLING[code];
      return [model, value, ms.map(([label, amountKeur, st]: [string, number, string]) => ({ label, amountKeur, status: STATUS[st] }))];
    }
    const tot = c.amount + c.amendments.filter((a: any[]) => a[2] === 'Signed').reduce((s: number, a: any[]) => s + a[1], 0);
    return ['Client · milestones', tot, c.milestones.map(([id, label, pct, , st]: any[]) => ({ label: `${id} ${label.split(' (')[0]}`, amountKeur: Math.round((tot * pct) / 100), status: STATUS[ov[id] ?? st] }))];
  };
  const IN = [1350, 0, 1080, 0, 1350, 585];
  const OUT = [820, 760, 700, 640, 560, 520];
  const cashAll = projects.filter((p) => P.BILLING[p.code] && P.EXEC_STAGES.includes(p.status));

  const rowOf = (p: (typeof projects)[number], ov: Record<string, string> = {}) => {
    const [model, contract, ms] = billingOf(p.code, ov);
    const r = billingRollup(contract, ms);
    const m = marginPct(contract, p.budget);
    return {
      code: p.code, name: p.name, model, contract: contract ? f(contract) : '—', invoiced: contract ? f(r.invoicedKeur) : '—', paid: contract ? f(r.paidKeur) : '—',
      outstanding: contract ? f(r.outstandingKeur) : '—', outColor: r.outstandingKeur > 0 ? LO : 'var(--color-neutral-400)', cost: f(p.actual),
      marginText: m != null ? `${m}%` : '—', marginColor: marginAlert(m) ? LO : OK, next: r.next ? `${r.next.label} · ${f(r.next.amountKeur)}` : '—',
      invW: `${r.invoicedPct}%`, paidW: `${r.paidPct}%`, isInternal: r.internal,
    };
  };

  it.each(ZONES)('zone %s: rows, KPI tiles and bars', (z) => {
    const g = G.cash.en.director[String(z)];
    const rows = cashAll.filter((p) => !z || zoneOf(p.code) === z);
    expect(rows.map((p) => rowOf(p))).toEqual(g.rows);
    expect(g.zoneEmpty).toBe(!!z && !rows.length);
    const cv = (xs: typeof rows) => xs.reduce((a, p) => a + billingOf(p.code)[1], 0);
    const share = z ? (cv(cashAll) ? cv(rows) / cv(cashAll) : 0) : 1;
    const months = IN.map((v, i) => ({ cashInKeur: Math.round(v * share), cashOutKeur: Math.round(OUT[i] * share) }));
    const roll = rows.map((p) => billingOf(p.code)).map(([, c, ms]) => ({ c, r: billingRollup(c, ms) }));
    const kpis = [
      [f(roll.reduce((a, x) => a + x.c, 0)), clientProjectsText(roll.filter((x) => !x.r.internal).length, roll.filter((x) => x.r.internal).length)],
      [f(roll.reduce((a, x) => a + x.r.invoicedKeur, 0)), 'Milestones reached or monthly progress'],
      [f(roll.reduce((a, x) => a + x.r.receivableKeur, 0)), 'Invoiced, not yet paid'],
      [f(netCash(months), true), 'Billing plan minus forecast spend'],
      [f(lowestCumulative(months), true), 'November — before M3 payment lands'],
    ];
    // Deliberate deviation: singular "1 client project" (the prototype prints "1 client projects").
    expect(kpis).toEqual(g.kpis.map((k: any, i: number) => [k.value, i === 0 ? k.sub.replace(/^1 client projects/, '1 client project') : k.sub]));
    expect(g.kpis.map((k: any) => k.color)).toEqual([OK, OK, LO, OK, LO]);
    const bars = cashBars(months);
    expect(bars.map((b, i) => ({ label: P.CASH_M[i], inH: `${b.inPct}%`, outH: `${b.outPct}%`, net: netLabel(b.netKeur), netColor: LO, cum: f(b.cumKeur, true) }))).toEqual(g.bars);
  });

  it('an invoice issued on the Billing screen (M4 invoiced) flows into the row', () => {
    expect(rowOf(projects[0], { M4: 'Invoiced' })).toEqual(G.cash.m4Invoiced);
  });

  it('masked margin for viewers without margin rights', () => {
    expect(G.cash.en.depthead.null.rows.map((r: any) => r.marginText)).toEqual(['•••', '•••', '•••', '•••', '•••']);
  });

  it('bar scale grows past 1 500 k€ instead of overflowing; empty window', () => {
    expect(cashBars([{ cashInKeur: 3000, cashOutKeur: 750 }]).map((b) => [b.inPct, b.outPct])).toEqual([[100, 25]]);
    expect(lowestCumulative([])).toBe(0);
    expect(netLabel(0)).toBe('+0k');
    expect(clientProjectsText(1, 0)).toBe('1 client project · 0 internal');
  });
});
